import json
from collections import defaultdict, OrderedDict
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path

RAW_DIR = Path('/app/raw_logs')
OUT_DIR = Path('/app/recovered_logs')
ERROR_MARKERS = ('quota exceeds', 'api error', 'timeout')


def load_jsonl(path):
    records = []
    with path.open('r', encoding='utf-8') as f:
        for line_no, line in enumerate(f, 1):
            line = line.strip()
            if not line:
                continue
            try:
                records.append(json.loads(line))
            except json.JSONDecodeError as exc:
                raise ValueError(f'{path}:{line_no}: invalid JSON: {exc}') from exc
    return records


def is_error(value):
    text = str(value).lower()
    return any(marker in text for marker in ERROR_MARKERS)


def assign_runs(records, value_key):
    by_qid = defaultdict(list)
    for rec in records:
        by_qid[rec['question_id']].append(rec)

    runs = {1: [], 2: [], 3: []}
    for qid in sorted(by_qid):
        group = sorted(by_qid[qid], key=lambda r: r['timestamp'])
        if len(group) != 3:
            raise ValueError(f'{value_key} question_id {qid} has {len(group)} records, expected 3')
        for idx, rec in enumerate(group, 1):
            # Rebuild objects to enforce key order and remove any unexpected fields.
            runs[idx].append(OrderedDict([
                ('timestamp', rec['timestamp']),
                ('question_id', rec['question_id']),
                (value_key, rec[value_key]),
            ]))

    for idx in runs:
        runs[idx].sort(key=lambda r: r['timestamp'])
    return runs


def write_jsonl(path, records):
    with path.open('w', encoding='utf-8', newline='\n') as f:
        for rec in records:
            f.write(json.dumps(rec, separators=(',', ':'), ensure_ascii=False))
            f.write('\n')


def accuracy_for_run(generator_records, judge_records):
    gen_by_qid = {r['question_id']: r for r in generator_records}
    judge_by_qid = {r['question_id']: r for r in judge_records}
    correct = 0
    total = 0

    for qid in sorted(set(gen_by_qid) & set(judge_by_qid)):
        pred = gen_by_qid[qid]['prediction']
        target = judge_by_qid[qid]['target']
        if is_error(pred) or is_error(target):
            continue
        try:
            pred_int = int(pred)
            target_int = int(target)
        except (TypeError, ValueError):
            continue
        total += 1
        if pred_int == target_int:
            correct += 1

    if total == 0:
        accuracy = None
    else:
        accuracy = float((Decimal(correct) / Decimal(total)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
    return correct, total, accuracy


def main():
    OUT_DIR.mkdir(parents=True, exist_ok=True)

    generator_records = load_jsonl(RAW_DIR / 'generator.log')
    judge_records = load_jsonl(RAW_DIR / 'judge.log')

    gen_runs = assign_runs(generator_records, 'prediction')
    judge_runs = assign_runs(judge_records, 'target')

    results = {'runs': []}
    for run_index in (1, 2, 3):
        write_jsonl(OUT_DIR / f'run_{run_index}_generator.jsonl', gen_runs[run_index])
        write_jsonl(OUT_DIR / f'run_{run_index}_judge.jsonl', judge_runs[run_index])
        correct, total, accuracy = accuracy_for_run(gen_runs[run_index], judge_runs[run_index])
        results['runs'].append(OrderedDict([
            ('run_index', run_index),
            ('correct', correct),
            ('total', total),
            ('accuracy', accuracy),
        ]))

    with (OUT_DIR / 'results.json').open('w', encoding='utf-8', newline='\n') as f:
        json.dump(results, f, indent=2, ensure_ascii=False)
        f.write('\n')


if __name__ == '__main__':
    main()
