ERROR_MARKERS = ('quota exceeds', 'api error', 'timeout')


def load_jsonl(path):
    return [json.loads(line) for line in path.read_text(encoding='utf-8').splitlines() if line]


def is_error(value):
    text = str(value).lower()
    return any(marker in text for marker in ERROR_MARKERS)


def expected_runs(raw_path, value_key):
    by_qid = defaultdict(list)
    for rec in load_jsonl(raw_path):
        by_qid[rec['question_id']].append(rec)
    assert len(by_qid) == 10

    runs = {1: [], 2: [], 3: []}
    for qid, records in by_qid.items():
        assert len(records) == 3
        for run_index, rec in enumerate(sorted(records, key=lambda r: r['timestamp']), 1):
            runs[run_index].append(OrderedDict([
                ('timestamp', rec['timestamp']),
                ('question_id', rec['question_id']),
                (value_key, rec[value_key]),
            ]))
    for run_index in runs:
        runs[run_index].sort(key=lambda r: r['timestamp'])
    return runs


def read_strict_jsonl(path, keys):
    data = path.read_bytes()
    assert data, f'{path} is empty'
    assert data.endswith(b'\n'), f'{path} must end with newline'
    lines = data.splitlines(keepends=True)
    assert len(lines) == 10, f'{path} should contain exactly 10 lines'

    records = []
    for i, raw_line in enumerate(lines, 1):
        assert raw_line.endswith(b'\n'), f'{path}:{i} missing newline'
        assert raw_line.count(b'\n') == 1, f'{path}:{i} should have one newline terminator'
        line = raw_line[:-1].decode('utf-8')
        assert line, f'{path}:{i} blank line'
        assert ': ' not in line and ', ' not in line, f'{path}:{i} is not compact JSON'
        rec = json.loads(line, object_pairs_hook=OrderedDict)
        assert list(rec.keys()) == keys, f'{path}:{i} key order mismatch: {list(rec.keys())}'
        assert json.dumps(rec, separators=(',', ':'), ensure_ascii=False) == line, f'{path}:{i} not canonical compact JSON'
        records.append(rec)
    assert [r['timestamp'] for r in records] == sorted(r['timestamp'] for r in records), f'{path} not sorted by timestamp'
    assert len({r['question_id'] for r in records}) == 10, f'{path} should have one record per question_id'
    return records


def compute_expected_results(gen_runs, judge_runs):
    runs = []
    for run_index in (1, 2, 3):
        gen_by_qid = {r['question_id']: r for r in gen_runs[run_index]}
        judge_by_qid = {r['question_id']: r for r in judge_runs[run_index]}
        correct = 0
        total = 0
        for qid in sorted(set(gen_by_qid) & set(judge_by_qid)):
            pred = gen_by_qid[qid]['prediction']
            target = judge_by_qid[qid]['target']
            if is_error(pred) or is_error(target):
                continue
            try:
                pred_int = int(pred)
                target_int = int(target)
            except (TypeError, ValueError):
                continue
            total += 1
            correct += int(pred_int == target_int)
        accuracy = None if total == 0 else float((Decimal(correct) / Decimal(total)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
        runs.append({'run_index': run_index, 'correct': correct, 'total': total, 'accuracy': accuracy})
    return {'runs': runs}


def test_recovered_logs_and_results_are_correct():
    expected_gen = expected_runs(RAW_DIR / 'generator.log', 'prediction')
    expected_judge = expected_runs(RAW_DIR / 'judge.log', 'target')

    actual_gen = {}
    actual_judge = {}
    for run_index in (1, 2, 3):
        actual_gen[run_index] = read_strict_jsonl(OUT_DIR / f'run_{run_index}_generator.jsonl', ['timestamp', 'question_id', 'prediction'])
        actual_judge[run_index] = read_strict_jsonl(OUT_DIR / f'run_{run_index}_judge.jsonl', ['timestamp', 'question_id', 'target'])
        assert actual_gen[run_index] == expected_gen[run_index]
        assert actual_judge[run_index] == expected_judge[run_index]

    expected_results = compute_expected_results(expected_gen, expected_judge)
    actual_results = json.loads((OUT_DIR / 'results.json').read_text(encoding='utf-8'))
    assert actual_results == expected_results
